function updateScene(){
  const f=finishes[surface][selected[surface]];
  $("finishName").textContent=f.name;
  $("finishMeta").textContent=f.meta;
  $("finishSwatch").style.background=f.texture;
  $("activeFinishLabel").textContent=f.name+" ("+surface+")";
  const customRow=$("customColorPickerContainer");
  if(customRow)customRow.style.display=surface==="wall"?"flex":"none";
  $("finishOptions").innerHTML=finishes[surface].map((x,i)=>`<button class="finish-option ${i===selected[surface]?"active":""}" data-finish="${i}"><span class="finish-texture" style="background:${x.texture}"></span><b>${esc(x.name)}</b></button>`).join("");
  applySurfaceToAiRoom(surface,f);
}

function setSurface(s){
  surface=s;
  document.querySelectorAll(".surface-btn").forEach(b=>b.classList.toggle("active",b.dataset.surface===s));
  updateScene();
  if(window.buildAiRoom)window.buildAiRoom.apply(surface,finishes[surface][selected[surface]]);
}
