function quote(id){const s=suppliers.find(x=>x.id===id);modal("Request a supplier quotation",`<p>Prepare a quote request draft. This prototype saves it in this browser; it does not transmit a request to the business.</p><div class="field"><label>Supplier</label><select id="qSup"><option value="">Choose later</option>${suppliers.map(x=>`<option value="${x.id}" ${s&&x.id===s.id?"selected":""}>${esc(x.name)}</option>`).join("")}</select></div><div class="field"><label>Material</label><select id="qMat">${products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join("")}</select></div><div class="field"><label>Quantity and unit</label><input id="qQty" placeholder="e.g. 100 sq. ft. or 25 bags" required></div><div class="field"><label>Site area and specifications</label><textarea id="qNotes" placeholder="Vellore locality, brand, grade, expected delivery date..."></textarea></div>`,close=>{if(!$("qQty").value.trim()){toast("Enter an estimated quantity.");return}const arr=JSON.parse(localStorage.getItem("buildai_quotes")||"[]");arr.push({supplier:$("qSup").value,product:$("qMat").value,quantity:$("qQty").value,notes:$("qNotes").value,created:new Date().toISOString()});localStorage.setItem("buildai_quotes",JSON.stringify(arr));close();toast("Request draft saved locally. Contact supplier to submit it.")},"Save request")}
