function placeDirectOrder(){
 if(!cart.length){toast("Cart is empty.");return;}
 const assortData=window.buildaiAssortment;
 const metricsData=window.supplierMetrics;
 if(!assortData||!metricsData){toast("Cannot place direct order: supplier data unavailable.");return;}
 const groupId="DIRECT-"+Date.now().toString(36).toUpperCase();
 const session=JSON.parse(sessionStorage.getItem("buildai_demo_session")||"null");
 const now=new Date().toISOString();
 const shopMap=new Map();
 cart.forEach(item=>{
  const candidates=suppliers.filter(s=>(assortData[s.id]||[]).includes(item.id));
  if(!candidates.length)return;
  candidates.sort((a,b)=>((metricsData[b.id]||{score:4}).score-(metricsData[a.id]||{score:4}).score));
  const best=candidates[0];
  if(!shopMap.has(best.id))shopMap.set(best.id,{supplier:best,items:[]});
  shopMap.get(best.id).items.push(item);
 });
 const existing=JSON.parse(localStorage.getItem("buildai_supplier_requests")||"[]");
 shopMap.forEach((shop,supplierId)=>{
  const m=metricsData[supplierId]||{score:4,days:3,fee:650};
  const items=shop.items.map(it=>({productId:it.id,name:it.name,category:it.category,quantity:it.qty,unit:it.unit,indicativeUnitPrice:it.price,indicativeSubtotal:it.price*it.qty,specification:it.spec}));
  const sub=items.reduce((n,it)=>n+it.indicativeSubtotal,0);
  existing.push({id:groupId+"-"+supplierId,groupId,supplierId,supplierName:shop.supplier.name,builderEmail:(session&&session.email)||"builder@buildai.demo",projectName:"Direct Cart Order",deliveryArea:"Vellore, Tamil Nadu",budget:0,deadlineDays:3,priority:"balanced",createdAt:now,items,indicativeSubtotal:sub,indicativeDeliveryFee:m.fee,indicativeTotal:sub+m.fee,status:"Pending response",supplierQuote:null,supplierNote:"",updatedAt:null});
 });
 localStorage.setItem("buildai_supplier_requests",JSON.stringify(existing));
 try {
  const newDirectReqs = existing.filter(r => r.groupId === groupId);
  fetch("/api/requests", {
   method: "POST",
   headers: { "Content-Type": "application/json" },
   body: JSON.stringify(newDirectReqs)
  }).catch(()=>{});
 } catch(e){}
 cart.length=0;
 $("cartCount").textContent="0";
 const root=$("modalRoot");if(root)root.innerHTML="";
 toast("Direct order placed! Switch to supplier login to view it.");
}
function productPreview(id){
  const p=products.find(x=>x.id===id);
  if(!p) return;
  
  // 1. All Paints & Custom Wall Colors
  if(p.category==="Paints" || p.color){
    setSurface("wall");
    const colorHex = p.color || "#E9E1D4";
    applyCustomWallColor(colorHex, p.name);
    const customInput=document.getElementById("customWallColor");
    if(customInput) customInput.value=colorHex;
    const customHex=document.getElementById("customColorHex");
    if(customHex) customHex.textContent=colorHex.toUpperCase();
    scroll("studioSection");
    toast("✦ AI Room transformed with wall paint: " + p.name);
    return;
  }
  
  // 2. Marbles, Stones, Tiles & Flooring Products
  if(["Tiles", "Stones", "LVT Flooring", "SPC Flooring", "Modular Carpet Planks"].includes(p.category) || p.name.toLowerCase().includes("marble") || p.name.toLowerCase().includes("tile") || p.name.toLowerCase().includes("stone")){
    setSurface("floor");
    applyCustomFloorProduct(p);
    scroll("studioSection");
    toast("✦ AI Room transformed with marble/floor surface: " + p.name);
    return;
  }
  
  // 3. Laminates, Veneers, Plywood & Architectural Wood Panels
  if(["Laminates", "Veneers", "Plywood", "Skirting Boards"].includes(p.category) || p.name.toLowerCase().includes("laminate") || p.name.toLowerCase().includes("veneer") || p.name.toLowerCase().includes("wood")){
    setSurface("wood");
    applyCustomWoodProduct(p);
    scroll("studioSection");
    toast("✦ AI Room transformed with feature wall panel: " + p.name);
    return;
  }
  
  // Default fallback for structural items
  scroll("studioSection");
  toast("Exploring finishes in AI Material Studio for " + p.name);
}
async function loadMap(){if(mapInit||!window.L)return;mapInit=true;map=L.map("supplierMap",{scrollWheelZoom:false}).setView([12.9165,79.1325],12);L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);const bounds=[[12.9165,79.1325]];const layer=L.circleMarker([12.9165,79.1325],{radius:6,color:"#586477",fillColor:"#8e98a5",fillOpacity:.9,weight:2}).addTo(map).bindPopup("<b>Vellore city reference</b><div>City-level reference point, not a supplier.</div>");mapMarkers.city=layer;$("openFullMap").href="https://www.openstreetmap.org/#map=13/12.9165/79.1325";for(let i=0;i<suppliers.length;i++){const s=suppliers[i];try{const url="https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&countrycodes=in&q="+encodeURIComponent(s.mapQuery);const r=await fetch(url,{headers:{Accept:"application/json"}});const hits=r.ok?await r.json():[];if(hits&&hits.length){const p=[Number(hits[0].lat),Number(hits[0].lon)];const m=L.marker(p).addTo(map);m.bindPopup(`<b>${esc(s.name)}</b><div>${esc(s.address)}</div><div style="font-size:10px;color:#697589;margin-top:5px">Map point returned for this address query; verify the entrance before travel.</div><a target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s.mapQuery)}">Google Maps directions ↗</a>`);mapMarkers[s.id]=m;bounds.push(p)}else{mapMarkers[s.id]=null}}catch(e){mapMarkers[s.id]=null}if(i<suppliers.length-1)await new Promise(resolve=>setTimeout(resolve,1100))}
map.fitBounds(bounds,{padding:[25,25],maxZoom:14});setTimeout(()=>map.invalidateSize(),250);filterMarkers();const absent=suppliers.filter(s=>!mapMarkers[s.id]);if(absent.length)toast(absent.length+" supplier pin(s) could not be geocoded; use each supplier's Directions link.")}
function filterMarkers(){if(!mapInit)return;const visible=new Set([...document.querySelectorAll("[data-supplier-card]")].map(el=>el.dataset.supplierCard));suppliers.forEach(s=>{const m=mapMarkers[s.id];if(!m)return;if(visible.has(s.id)){if(!map.hasLayer(m))m.addTo(map)}else if(map.hasLayer(m))map.removeLayer(m)})}
