function initAiRoomVisualizer(){
  const lightingBtn=$("aiLightingToggle");
  const lightingOverlay=$("aiLightingOverlay");
  const customColorInput=$("customWallColor");
  const customColorHex=$("customColorHex");

  if(lightingBtn&&lightingOverlay){
    lightingBtn.onclick=()=>{
      const isWarm=lightingOverlay.classList.toggle("warm-mode");
      lightingBtn.textContent=isWarm?"🌙 Warm ambient lighting":"☀️ Natural daylight";
      toast(isWarm?"Ambient warm evening lighting enabled.":"Natural daylight lighting enabled.");
    };
  }
  if(customColorInput){
    customColorInput.addEventListener("input",e=>{
      const hex=e.target.value;
      if(customColorHex)customColorHex.textContent=hex;
      applyCustomWallColor(hex);
    });
  }
  window.buildAiRoom={
    apply:(surf,f)=>applySurfaceToAiRoom(surf,f)
  };
  return true;
}
function renderMapButtons(){const wrap=$("mapSupplierButtons");if(!wrap)return;wrap.innerHTML=suppliers.map(s=>'<button type="button" class="'+(selectedMapSupplier===s.id?"active":"")+'" data-map-pick="'+esc(s.id)+'">'+esc(s.name)+'</button>').join("")}
function loadMap(id){if(!suppliers.length)return;selectedMapSupplier=id||selectedMapSupplier||suppliers[0].id;const s=suppliers.find(x=>x.id===selectedMapSupplier)||suppliers[0];selectedMapSupplier=s.id;mapInit=true;renderMapButtons();const mapSrc="https://maps.google.com/maps?q="+encodeURIComponent(s.mapQuery)+"&output=embed";$("supplierMap").innerHTML='<iframe title="Google Maps location for '+esc(s.name)+'" loading="lazy" referrerpolicy="no-referrer-when-downgrade" src="'+mapSrc+'" allowfullscreen></iframe>';$("openFullMap").href="https://www.google.com/maps/search/?api=1&query="+encodeURIComponent(s.mapQuery);$("openFullMap").setAttribute("aria-label","Open "+s.name+" in Google Maps")}

function syncCategoryCounts(){
  const counts={All: products.length};
  products.forEach(p=>{
    counts[p.category]=(counts[p.category]||0)+1;
  });
  document.querySelectorAll(".sidebar .category").forEach(b=>{
    const cat=b.dataset.category;
    if(!cat)return;
    const cnt=counts[cat]||0;
    const iconSpan=b.querySelector("span");
    const icon=iconSpan?iconSpan.textContent:"▦";
    b.innerHTML=`<span>${icon}</span> ${cat==="All"?"All categories":cat} (${cnt})`;
  });
  const catDrop=document.getElementById("categoryFilterDropdown");
  if(catDrop){
    Array.from(catDrop.options).forEach(opt=>{
      const cat=opt.value;
      const cnt=counts[cat]||0;
      opt.textContent=`${cat==="All"?"All categories":cat} (${cnt})`;
    });
  }
}

syncCategoryCounts();
