(async function hydrateMarketplace(){
 try{
  const results=await Promise.all([fetch("/api/materials"),fetch("/api/suppliers")]);
  if(results[0].ok){const data=await results[0].json();if(Array.isArray(data.materials)&&data.materials.length){products.splice(0,products.length,...data.materials.map(p=>({...p,price:Number(p.price||0),tag:p.preview_surface==="floor"||p.preview_surface==="wall"||p.preview_surface==="wood"?"Preview":"Catalogue"})));window.products = products;renderProducts();syncCategoryCounts()}}
  if(results[1].ok){const data=await results[1].json();if(Array.isArray(data.suppliers)&&data.suppliers.length){suppliers.splice(0,suppliers.length,...data.suppliers.map(s=>({...s,source:s.source||s.website,sourceLabel:s.sourceLabel||"Public business listing",mapQuery:s.mapQuery||s.map_query||s.address,categories:Array.isArray(s.categories)?s.categories:[]})));renderSuppliers()}}
 }catch(e){console.warn("Using built-in catalogue fallback; marketplace API is not available.",e)}
})();
let searchDebounceTimer = null;
function fastSearchRender(delay = 40) {
  clearTimeout(searchDebounceTimer);
  searchDebounceTimer = setTimeout(() => {
    renderProducts();
  }, delay);
}
const catSearchInput = $("catalogueSearchInput");
const topSearchInput = $("searchInput");
if(catSearchInput){
  catSearchInput.addEventListener("input", () => {
    if(topSearchInput && topSearchInput.value !== catSearchInput.value) {
      topSearchInput.value = catSearchInput.value;
    }
    fastSearchRender(40);
  });
}
if(topSearchInput){
  topSearchInput.addEventListener("input", () => {
    if(catSearchInput && catSearchInput.value !== topSearchInput.value) {
      catSearchInput.value = topSearchInput.value;
    }
    fastSearchRender(40);
  });
}

// Global capturing listener for passport & specs buttons
document.addEventListener("click", function(e){
  const spec = e.target.closest("[data-passport], .passport-btn");
  if(spec){
    e.preventDefault();
    e.stopPropagation();
    const pid = spec.dataset.passport || spec.getAttribute("data-passport");
    if(pid && typeof window.showMaterialPassport === "function"){
      window.showMaterialPassport(pid);
    }
  }
}, true);
